"""Machine-readable formulas, input contracts, directions, and limitations."""

from __future__ import annotations

import json
from pathlib import Path

METRIC_DEFINITIONS = {
    "rmse": {"abbreviation": "RMSE", "full_form": "Root Mean Square Error", "formula": "sqrt(mean((y_true - y_pred)^2))", "purpose": "Typical squared-error magnitude in target units.", "inputs": "Finite numeric target and continuous prediction vectors.", "probability_or_class": "Continuous prediction", "desirable": "lower", "limitations": "Sensitive to large errors; here the target is a binary class indicator, not a separate regression target."},
    "mse": {"abbreviation": "MSE", "full_form": "Mean Squared Error", "formula": "mean((y_true - y_pred)^2)", "purpose": "Average squared prediction error.", "inputs": "Finite numeric target and continuous prediction vectors.", "probability_or_class": "Continuous prediction", "desirable": "lower", "limitations": "Squared target units; here calculated against a binary class indicator."},
    "mae": {"abbreviation": "MAE", "full_form": "Mean Absolute Error", "formula": "mean(abs(y_true - y_pred))", "purpose": "Average absolute prediction error.", "inputs": "Finite numeric target and continuous prediction vectors.", "probability_or_class": "Continuous prediction", "desirable": "lower", "limitations": "Here it is the mean absolute deviation of probabilities from binary labels."},
    "mape": {"abbreviation": "MAPE", "full_form": "Mean Absolute Percentage Error", "formula": "mean(abs((y_true - y_pred) / y_true)) * 100", "purpose": "Average absolute error relative to target magnitude.", "inputs": "Finite numeric vectors; every y_true must be nonzero.", "probability_or_class": "Continuous prediction", "desirable": "lower", "limitations": "Undefined for this binary classification target because licit labels are zero; zeros are not dropped or altered."},
    "r2": {"abbreviation": "R²", "full_form": "Coefficient of Determination", "formula": "1 - sum((y_true-y_pred)^2) / sum((y_true-mean(y_true))^2)", "purpose": "Error relative to predicting the target mean.", "inputs": "Finite numeric vectors with nonconstant y_true.", "probability_or_class": "Continuous prediction", "desirable": "higher", "limitations": "Can be negative; this is descriptive when applied to binary labels and class probabilities."},
    "nrmse": {"abbreviation": "NRMSE", "full_form": "Normalized Root Mean Square Error", "formula": "RMSE / (max(y_true) - min(y_true))", "purpose": "Scale RMSE by the target range.", "inputs": "Finite numeric vectors with nonzero target range.", "probability_or_class": "Continuous prediction", "desirable": "lower", "limitations": "Undefined for constant targets; binary-label range is 1 when both classes are present."},
    "medae": {"abbreviation": "MedAE", "full_form": "Median Absolute Error", "formula": "median(abs(y_true - y_pred))", "purpose": "Robust central absolute prediction error.", "inputs": "Finite numeric target and continuous prediction vectors.", "probability_or_class": "Continuous prediction", "desirable": "lower", "limitations": "May be zero even when some examples have substantial errors."},
    "bias": {"abbreviation": "Bias / ME", "full_form": "Mean Error", "formula": "mean(y_pred - y_true)", "purpose": "Measure signed average over- or underprediction.", "inputs": "Finite numeric target and continuous prediction vectors.", "probability_or_class": "Continuous prediction", "desirable": "near zero; inspect sign and magnitude", "limitations": "Positive means overprediction; negative means underprediction. Not ranked as simply higher or lower."},
    "accuracy": {"abbreviation": "Accuracy", "full_form": "Classification Accuracy", "formula": "(TP + TN) / (TP + TN + FP + FN)", "purpose": "Fraction of correct hard classifications.", "inputs": "Binary true labels and binary predicted classes.", "probability_or_class": "Predicted class", "desirable": "higher", "limitations": "Can conceal poor minority-class performance under imbalance."},
    "precision": {"abbreviation": "Precision", "full_form": "Positive Predictive Value", "formula": "TP / (TP + FP)", "purpose": "Reliability of illicit predictions.", "inputs": "Binary true labels and predicted classes; requires predicted positives.", "probability_or_class": "Predicted class", "desirable": "higher", "limitations": "Undefined if no examples are predicted positive."},
    "recall": {"abbreviation": "Recall", "full_form": "Sensitivity / True Positive Rate", "formula": "TP / (TP + FN)", "purpose": "Fraction of illicit transactions detected.", "inputs": "Binary true labels and predicted classes; requires actual positives.", "probability_or_class": "Predicted class", "desirable": "higher", "limitations": "Undefined if the evaluation population has no positives."},
    "f1_score": {"abbreviation": "F1-score", "full_form": "Harmonic Mean of Precision and Recall", "formula": "2*TP / (2*TP + FP + FN)", "purpose": "Balance positive-class precision and recall.", "inputs": "Binary true labels and predicted classes.", "probability_or_class": "Predicted class", "desirable": "higher", "limitations": "Ignores true negatives; undefined if there are no actual or predicted positives."},
    "specificity": {"abbreviation": "Specificity", "full_form": "True Negative Rate", "formula": "TN / (TN + FP)", "purpose": "Fraction of licit transactions correctly rejected as illicit.", "inputs": "Binary true labels and predicted classes; requires actual negatives.", "probability_or_class": "Predicted class", "desirable": "higher", "limitations": "Undefined if the evaluation population has no negatives."},
    "auc_roc": {"abbreviation": "AUC-ROC", "full_form": "Area Under the Receiver Operating Characteristic Curve", "formula": "P(score_positive > score_negative), with half credit for ties", "purpose": "Threshold-independent ranking discrimination.", "inputs": "Binary labels and positive-class probabilities; both classes required.", "probability_or_class": "Probability", "desirable": "higher", "limitations": "Undefined for a single-class sample and can look strong under severe imbalance."},
    "log_loss": {"abbreviation": "Log Loss", "full_form": "Binary Cross-Entropy Loss", "formula": "-mean(y*log(p) + (1-y)*log(1-p))", "purpose": "Assess probabilistic accuracy and penalize confident errors.", "inputs": "Binary labels and positive-class probabilities in [0,1].", "probability_or_class": "Probability", "desirable": "lower", "limitations": "Probabilities are clipped to [1e-15, 1-1e-15] for finite log calculations."},
    "mcc": {"abbreviation": "MCC", "full_form": "Matthews Correlation Coefficient", "formula": "(TP*TN - FP*FN) / sqrt((TP+FP)(TP+FN)(TN+FP)(TN+FN))", "purpose": "Single balanced summary of binary classification quality.", "inputs": "Binary true labels and predicted classes.", "probability_or_class": "Predicted class", "desirable": "higher", "limitations": "Undefined when a confusion-matrix marginal makes the denominator zero."},
    "cohens_kappa": {"abbreviation": "Cohen's κ", "full_form": "Cohen's Kappa Coefficient", "formula": "(observed agreement - expected agreement) / (1 - expected agreement)", "purpose": "Agreement beyond chance under observed label marginals.", "inputs": "Binary true labels and predicted classes.", "probability_or_class": "Predicted class", "desirable": "higher", "limitations": "Undefined when expected agreement is 1; sensitive to prevalence and marginals."},
    "balanced_accuracy": {"abbreviation": "Balanced Accuracy", "full_form": "Average Class Recall", "formula": "(TP/(TP+FN) + TN/(TN+FP)) / 2", "purpose": "Give equal weight to illicit and licit recall.", "inputs": "Binary true labels and predicted classes; both classes required.", "probability_or_class": "Predicted class", "desirable": "higher", "limitations": "Undefined if either true class is absent."},
}


def definitions_as_json(*, indent: int | None = 2) -> str:
    """Serialize all metric definitions to JSON text."""
    return json.dumps(METRIC_DEFINITIONS, indent=indent, sort_keys=True, allow_nan=False)


def export_definitions(path: str | Path) -> Path:
    """Write metric definitions to a caller-selected JSON path."""
    target = Path(path)
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(definitions_as_json() + "\n", encoding="utf-8")
    return target
